INSERT INTO artigos (slug,status,tipo,titulo,titulo_original,autor,autor_citacao,afiliacao,tradutor,periodico,volume,numero,ano,mes,paginas_original,editora_original,url_original,area,tema,tema_en,resumo,resumo_en,resumo_editorial,palavras_chave,direitos,pdf_url,pdf_paginas,capa_url,publicado_em) VALUES
('snyman-abraao-galatas-genesis','publicado','traducao','Abraão em Gálatas e em Gênesis','Abraham in Galatians and in Genesis','S. D. Snyman','SNYMAN, S. D.','University of the Free State, Bloemfontein','Gabriel Cantarino','Acta Theologica','33','2','2013',NULL,'148–163','University of the Free State',NULL,'Teologia bíblica','Abraão · Gálatas e Gênesis','Abraham · Galatians and Genesis','O objetivo deste artigo é concentrar-se na representação de Abraão na carta aos Gálatas e no livro de Gênesis, respectivamente, e colocá-la em perspectiva. Quais são as semelhanças e diferenças na representação de Abraão nos livros bíblicos de Gálatas e Gênesis? Três promessas são feitas a Abraão em Gênesis 12:1-3: terra, descendência e bênção. Em cada uma das passagens investigadas, a ênfase recai principalmente (mas não exclusivamente) sobre uma das promessas: em Gênesis 12–25, sobre o problema da descendência; na literatura do exílio, sobre a promessa da terra; em Gálatas 3, sobre a bênção.','The aim of this article is to focus on the portrayal of Abraham in the letter to the Galatians and in the book of Genesis, respectively, and to put it in perspective. What are the similarities and differences in the portrayal of Abraham in the biblical books of Galatians and Genesis? Three promises are made to Abraham in Genesis 12:1-3: land, offspring and blessing. In each of the passages investigated, the emphasis falls mainly (but not exclusively) on one of the promises: in Genesis 12–25, on the problem of offspring; in the literature of the exile, on the promise of land; in Galatians 3, on the blessing.',0,'["Abraão", "Gênesis", "Gálatas", "promessas patriarcais", "bênção às nações", "Espírito", "Paulo e o Antigo Testamento", "exílio"]','Publicado com autorização de S. D. Snyman (20/11/2026). Os direitos do texto original pertencem a S. D. Snyman. Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, para fins de estudo, sem fins lucrativos.','/artigos/snyman-2013-abraao-galatas-genesis.pdf',16,'/artigos/snyman-2013-abraao-galatas-genesis-capa.jpg','2026-11-20 20:25:00');
